const root=$input.first().json||{};
const state=root.state||root.input?.state||{};
const sequence=root.sequence||root.input?.sequence||[];
const now=new Date(root.now||root.input?.now||new Date().toISOString());
if(!Array.isArray(sequence)||!sequence.length) return [{json:{success:false,component_id:'C1-E',component_version:'v1',error:{code:'NO_SEQUENCE_STEPS',message:'sequence[] is required.'},next_action:'configure_sequence'}}];
if(state.opted_out===true || state.replied===true || state.status==='stopped') return [{json:{success:true,component_id:'C1-E',component_version:'v1',sequence_status:'stopped',stop_reason:state.opted_out?'opted_out':state.replied?'reply_received':'manually_stopped',next_step:null,next_action:'no_send',error:null}}];
const completed=new Set(state.completed_step_ids||[]);const next=sequence.find(s=>!completed.has(s.id));
if(!next) return [{json:{success:true,component_id:'C1-E',component_version:'v1',sequence_status:'complete',next_step:null,next_action:'sequence_complete',error:null}}];
const due=new Date(now.getTime()+Math.max(0,Number(next.delay_hours||0))*3600000).toISOString();
return [{json:{success:true,component_id:'C1-E',component_version:'v1',sequence_status:'active',next_step:{...next,due_at:due},guardrails:{requires_approval:next.requires_approval!==false,check_suppression:true,stop_on_reply:true},next_action:'schedule_next_step',error:null}}];
